// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }
    function testFuzz_property(uint256 amount, address receiver) public {
        vm.assume(amount > 0);
        vm.assume(receiver != address(c) && receiver != address(this));
        // c holds no ether, so any positive amount exceeds its balance:
        // the reference must revert, the mutant (transfer(0)) succeeds.
        vm.prank(address(this)); // deployer is the owner
        bool ok;
        try c.sendTo(receiver, amount) { ok = true; } catch { ok = false; }
        assertTrue(!ok, "sendTo with amount > contract balance must revert");
    }
}
